def is_valid_dashed_credit_card(s):
    import re
    if not re.fullmatch(r'\d{4}-\d{4}-\d{4}-\d{4}', s):
        return False
    digits = s.replace('-', '')
    total = 0
    for i, ch in enumerate(reversed(digits)):
        d = int(ch)
        if i % 2 == 1:
            d *= 2
            if d > 9:
                d -= 9
        total += d
    return total % 10 == 0

def interleave_strings(s1, s2):
    out = []
    i = 0
    n = max(len(s1), len(s2))
    for i in range(n):
        if i < len(s1):
            out.append(s1[i])
        if i < len(s2):
            out.append(s2[i])
    return ''.join(out)

def sum_of_prime_factors(n):
    total = 0
    x = n
    p = 2
    while p * p <= x:
        if x % p == 0:
            total += p
            while x % p == 0:
                x //= p
        p += 1
    if x > 1:
        total += x
    return total

