def recursive_merge_sum_leaves(a, b):
    result = dict(a)
    for k, v in b.items():
        if k in result:
            if isinstance(result[k], dict) and isinstance(v, dict):
                result[k] = recursive_merge_sum_leaves(result[k], v)
            elif (isinstance(result[k], (int, float)) and not isinstance(result[k], bool)
                  and isinstance(v, (int, float)) and not isinstance(v, bool)):
                result[k] = result[k] + v
            else:
                result[k] = v
        else:
            result[k] = v
    return result

