def is_single_quoted_literal(s):
    if len(s) < 2 or s[0] != "'" or s[-1] != "'":
        return False
    inner = s[1:-1]
    i, n = 0, len(inner)
    while i < n:
        c = inner[i]
        if c == "'":
            return False
        if c == '\\':
            if i + 1 >= n or inner[i + 1] not in ('\\', "'"):
                return False
            i += 2
        else:
            i += 1
    return True

def is_valid_tags_with_attributes(s):
    import re
    pos = 0
    stack = []
    pattern = re.compile(r'<([a-z]+)[^<>]*>|</([a-z]+)>')
    while pos < len(s):
        m = pattern.match(s, pos)
        if not m:
            return False
        if m.group(1) is not None:
            stack.append(m.group(1))
        else:
            if not stack or stack[-1] != m.group(2):
                return False
            stack.pop()
        pos = m.end()
    return len(stack) == 0

def is_valid_gray_code_step(a, b):
    if len(a) != len(b) or len(a) == 0:
        return False
    if any(c not in '01' for c in a) or any(c not in '01' for c in b):
        return False
    diff = sum(1 for x, y in zip(a, b) if x != y)
    return diff == 1

def word_count_difference(text1, text2):
    c1 = {}
    for w in text1.split():
        c1[w] = c1.get(w, 0) + 1
    c2 = {}
    for w in text2.split():
        c2[w] = c2.get(w, 0) + 1
    keys = set(c1) | set(c2)
    return {k: c1.get(k, 0) - c2.get(k, 0) for k in keys}

import math
def count_common_divisors(a, b):
    g = math.gcd(a, b)
    count = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            count += 1 if i * i == g else 2
        i += 1
    return count

def count_char_type_groups(s):
    if not s:
        return 0
    def kind(ch):
        if ch.isalpha():
            return 'alpha'
        if ch.isdigit():
            return 'digit'
        return 'other'
    groups = 1
    for i in range(1, len(s)):
        if kind(s[i]) != kind(s[i-1]):
            groups += 1
    return groups

