def average_rank_across_two_lists(list1, list2):
    pos1 = {v: i for i, v in enumerate(list1)}
    pos2 = {v: i for i, v in enumerate(list2)}
    common = set(pos1) & set(pos2)
    return sorted(common, key=lambda x: ((pos1[x] + pos2[x]) / 2, x))

def rotate_matrix_90(matrix):
    if not matrix:
        return []
    n = len(matrix)
    return [[matrix[n-1-r][c] for r in range(n)] for c in range(n)]

def sum_even_fibonacci_below(n):
    a, b = 0, 1
    total = 0
    while a < n:
        if a % 2 == 0:
            total += a
        a, b = b, a + b
    return total

def can_form_palindrome(s):
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    odd = sum(1 for c in freq.values() if c % 2 == 1)
    return odd <= 1

